data class IptvSnapshot(
    val channels: List<Channel> = emptyList(),
    val programs: Map<String, ProgramInfo> = emptyMap(),
    val epgUrls: List<String> = emptyList(),
    val lastUpdatedMillis: Long = 0L,
    val status: String = "IPTV ainda não sincronizado"
)

class IptvRepository(context: Context) {
    private val directory = File(context.filesDir, "zapptv-cache").apply { mkdirs() }
    private val playlistFile = File(directory, "br.m3u")
    private val epgFile = File(directory, "br-epg.xml")

    fun loadCached(): IptvSnapshot {
        val parsed = parsePlaylist(playlistFile)
        val programs = XmlTvParser.parseCurrentPrograms(epgFile, parsed.channels)
        val updated = maxOf(playlistFile.lastModified(), epgFile.lastModified())

        return IptvSnapshot(
            channels = parsed.channels,
            programs = programs,
            epgUrls = parsed.epgUrls,
            lastUpdatedMillis = updated,
            status = when {
                parsed.channels.isEmpty() -> "Sem cache IPTV; usando canais integrados"
                programs.isEmpty() -> "IPTV em cache; EPG aguardando sincronização"
                else -> "IPTV e EPG carregados do cache"
            }
        )
    }

    fun refresh(force: Boolean = false): IptvSnapshot {
        var playlistNetworkOk = true
        var epgNetworkOk = true

        if (force || isStale(playlistFile, PLAYLIST_TTL_MS)) {
            playlistNetworkOk = download(
                url = DEFAULT_PLAYLIST_URL,
                target = playlistFile,
                maxBytes = MAX_PLAYLIST_BYTES
            )
        }

        val parsed = parsePlaylist(playlistFile)
        val epgUrl = parsed.epgUrls
            .firstOrNull { it.startsWith("https://", ignoreCase = true) }
            ?: DEFAULT_EPG_URL

        if (force || isStale(epgFile, EPG_TTL_MS)) {
            epgNetworkOk = download(
                url = epgUrl,
                target = epgFile,
                maxBytes = MAX_EPG_BYTES
            )
        }

        val programs = XmlTvParser.parseCurrentPrograms(epgFile, parsed.channels)
        val updated = maxOf(playlistFile.lastModified(), epgFile.lastModified())

        val status = when {
            parsed.channels.isEmpty() ->
                "IPTV indisponível; canais oficiais integrados continuam ativos"

            !playlistNetworkOk || !epgNetworkOk ->
                "IPTV ativo com cache; atualização de rede parcialmente indisponível"

            programs.isEmpty() ->
                "IPTV atualizado; guia EPG sem correspondências neste momento"

            else ->
                "IPTV e EPG atualizados"
        }

        return IptvSnapshot(
            channels = parsed.channels,
            programs = programs,
            epgUrls = parsed.epgUrls,
            lastUpdatedMillis = updated,
            status = status
        )
    }

    private fun parsePlaylist(file: File): ParsedIptvPlaylist {
        if (!file.isFile || file.length() == 0L) return ParsedIptvPlaylist(emptyList(), emptyList())
        return runCatching {
            BufferedReader(InputStreamReader(FileInputStream(file), Charsets.UTF_8)).use {
                IptvPlaylistParser.parse(it)
            }
        }.getOrDefault(ParsedIptvPlaylist(emptyList(), emptyList()))
    }

    private fun isStale(file: File, ttlMillis: Long): Boolean =
        !file.isFile ||
            file.length() == 0L ||
            System.currentTimeMillis() - file.lastModified() > ttlMillis

    private fun download(url: String, target: File, maxBytes: Long): Boolean {
        if (!url.startsWith("https://", ignoreCase = true)) return false
        val temp = File(target.parentFile, "${target.name}.tmp")
        var connection: HttpURLConnection? = null

        return runCatching {
            connection = (URL(url).openConnection() as HttpURLConnection).apply {
                instanceFollowRedirects = true
                connectTimeout = CONNECT_TIMEOUT_MS
                readTimeout = READ_TIMEOUT_MS
                requestMethod = "GET"
                setRequestProperty("User-Agent", USER_AGENT)
                setRequestProperty("Accept", "*/*")
                setRequestProperty("Accept-Encoding", "gzip")
            }

            val response = connection!!.responseCode
            require(response in 200..299) { "HTTP $response" }

            val raw = BufferedInputStream(connection!!.inputStream)
            val input: InputStream = if (
                connection!!.contentEncoding.equals("gzip", ignoreCase = true) ||
                url.endsWith(".gz", ignoreCase = true)
            ) {
                GZIPInputStream(raw)
            } else {
                raw
            }

            FileOutputStream(temp).use { output ->
                input.use { source ->
                    val buffer = ByteArray(DEFAULT_BUFFER_SIZE)
                    var total = 0L
                    while (true) {
                        val read = source.read(buffer)
                        if (read <= 0) break
                        total += read
                        require(total <= maxBytes) { "Resposta excedeu o limite seguro" }
                        output.write(buffer, 0, read)
                    }
                    output.fd.sync()
                }
            }

            require(temp.length() > 0L) { "Resposta vazia" }
            if (!temp.renameTo(target)) {
                temp.copyTo(target, overwrite = true)
                temp.delete()
            }
            target.setLastModified(System.currentTimeMillis())
            true
        }.getOrElse {
            temp.delete()
            false
        }.also {
            connection?.disconnect()
        }
    }

    companion object {
        const val DEFAULT_PLAYLIST_URL = "https://iptv-org.github.io/iptv/countries/br.m3u"
        const val DEFAULT_EPG_URL = "https://iptv-org.github.io/epg/guides/br/mi.tv.epg.xml"

        private const val USER_AGENT = "ZappTV/1.1 (Android TV)"
        private const val CONNECT_TIMEOUT_MS = 6_000
        private const val READ_TIMEOUT_MS = 15_000
        private const val PLAYLIST_TTL_MS = 12L * 60L * 60L * 1000L
        private const val EPG_TTL_MS = 4L * 60L * 60L * 1000L
        private const val MAX_PLAYLIST_BYTES = 8L * 1024L * 1024L
        private const val MAX_EPG_BYTES = 64L * 1024L * 1024L
    }
}

package com.mukasanches.zapptv.data

import android.content.Context

class PreferencesRepository(context: Context) {
    private val prefs = context.getSharedPreferences("zapptv", Context.MODE_PRIVATE)

    fun lastChannelId(): String? = prefs.getString(KEY_LAST_CHANNEL, null)

    fun setLastChannel(id: String) {
        prefs.edit().putString(KEY_LAST_CHANNEL, id).apply()
    }

    fun favorites(): Set<String> =
        prefs.getStringSet(KEY_FAVORITES, emptySet()).orEmpty().toSet()

    fun setFavorite(id: String, favorite: Boolean) {
        val updated = favorites().toMutableSet()
        if (favorite) updated += id else updated -= id
        prefs.edit().putStringSet(KEY_FAVORITES, updated).apply()
    }

    companion object {
        private const val KEY_LAST_CHANNEL = "last_channel"
        private const val KEY_FAVORITES = "favorites"
    }
}

package com.mukasanches.zapptv.data

import com.mukasanches.zapptv.model.Channel
import com.mukasanches.zapptv.model.ProgramInfo
import org.xml.sax.Attributes
import org.xml.sax.helpers.DefaultHandler
import java.io.File
import java.text.SimpleDateFormat
import java.util.Locale
import javax.xml.parsers.SAXParserFactory

object XmlTvParser {
    fun parseCurrentPrograms(
        file: File,
        channels: List<Channel>,
        now: Long = System.currentTimeMillis()
    ): Map<String, ProgramInfo> {
        if (!file.isFile || file.length() == 0L) return emptyMap()

        val channelIdsByEpg = channels
            .mapNotNull { channel -> channel.epgId?.let { it to channel.id } }
            .groupBy({ it.first }, { it.second })
        if (channelIdsByEpg.isEmpty()) return emptyMap()

        val result = linkedMapOf<String, ProgramInfo>()
        val factory = SAXParserFactory.newInstance().apply {
            isNamespaceAware = false
            isValidating = false
            runCatching { setFeature("http://xml.org/sax/features/external-general-entities", false) }
            runCatching { setFeature("http://xml.org/sax/features/external-parameter-entities", false) }
            runCatching { setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false) }
        }

        runCatching {
            val parser = factory.newSAXParser()
            parser.parse(file, CurrentProgramHandler(channelIdsByEpg, now, result))
        }

        return result
    }

    private class CurrentProgramHandler(
        private val channelIdsByEpg: Map<String, List<String>>,
        private val now: Long,
        private val result: MutableMap<String, ProgramInfo>
    ) : DefaultHandler() {
        private var active = false
        private var activeEpgId: String? = null
        private var startMillis: Long? = null
        private var endMillis: Long? = null
        private var currentField: String? = null
        private val text = StringBuilder()
        private var title: String? = null
        private var subtitle: String? = null
        private var description: String? = null

        override fun startElement(
            uri: String?,
            localName: String?,
            qName: String,
            attributes: Attributes
        ) {
            when (qName.lowercase(Locale.ROOT)) {
                "programme" -> {
                    resetProgram()
                    val epgId = attributes.getValue("channel") ?: return
                    if (epgId !in channelIdsByEpg) return

                    val start = parseXmlTvTime(attributes.getValue("start")) ?: return
                    val stop = parseXmlTvTime(attributes.getValue("stop")) ?: (start + SIX_HOURS_MS)
                    if (now < start || now >= stop) return

                    active = true
                    activeEpgId = epgId
                    startMillis = start
                    endMillis = stop
                }

                "title", "sub-title", "desc" -> if (active) {
                    currentField = qName.lowercase(Locale.ROOT)
                    text.setLength(0)
                }
            }
        }

        override fun characters(ch: CharArray, start: Int, length: Int) {
            if (active && currentField != null) text.append(ch, start, length)
        }

        override fun endElement(uri: String?, localName: String?, qName: String) {
            val element = qName.lowercase(Locale.ROOT)
            if (active && currentField == element) {
                val value = text.toString().trim().takeIf(String::isNotBlank)
                when (element) {
                    "title" -> if (title == null) title = value
                    "sub-title" -> if (subtitle == null) subtitle = value
                    "desc" -> if (description == null) description = value
                }
                currentField = null
                text.setLength(0)
            }

            if (element == "programme" && active) {
                val epgId = activeEpgId
                if (epgId != null) {
                    channelIdsByEpg[epgId].orEmpty().forEach { channelId ->
                        result.putIfAbsent(
                            channelId,
                            ProgramInfo(
                                channelId = channelId,
                                title = title ?: "Ao vivo",
                                subtitle = subtitle,
                                description = description,
                                startMillis = startMillis,
                                endMillis = endMillis
                            )
                        )
                    }
                }
                resetProgram()
            }
        }

        private fun resetProgram() {
            active = false
            activeEpgId = null
            startMillis = null
            endMillis = null
            currentField = null
            text.setLength(0)
            title = null
            subtitle = null
            description = null
        }
    }

    private fun parseXmlTvTime(value: String?): Long? {
        val raw = value?.trim().orEmpty()
        if (raw.isBlank()) return null

        val patterns = listOf(
            "yyyyMMddHHmmss Z",
            "yyyyMMddHHmm Z",
            "yyyyMMddHHmmss",
            "yyyyMMddHHmm"
        )

        for (pattern in patterns) {
            val parsed = runCatching {
                SimpleDateFormat(pattern, Locale.US).apply {
                    isLenient = false
                }.parse(raw)?.time
            }.getOrNull()
            if (parsed != null) return parsed
        }
        return null
    }

    private const val SIX_HOURS_MS = 6L * 60L * 60L * 1000L
}
